import{renderDiagram,renderCustomModel}from './visual.js?v=20261023-physicscomplete01';
import{circuit,vesselCases,vesselValid,valveFlow,bloodParts,gasSnapshot,exchangeCase,exchangeComparisons}from './circulation-models.js?v=20261023-physicscomplete01';
import{heartFigure,circuitFigure,vesselFigure,bloodFigure,lungFigure,valveFigure,circSvg}from './circulation-figures.js?v=20261023-physicscomplete01';
import{buildCirculation}from './circulation-meshes.js?v=20261023-physicscomplete01';
const opts=(pairs,v)=>'<option value="">Choose…</option>'+pairs.map(([k,t])=>`<option value="${k}" ${String(k)===String(v)?'selected':''}>${t}</option>`).join('');
const note='<p class="diagram-caption">Functional schematics, not anatomical measurements or real flow rates. Blood is never blue. Colours and sizes are symbolic; components are separately enlarged. Counterfactuals isolate one role.</p>';
export function showCirculation(kind='heart',w={}){
 const [base,variant]=kind.split(':');kind=base;if(kind==='blood'&&variant)w={component:variant,...w};if(kind==='vessels'&&variant)w={...vesselCases.find(v=>v.id===variant),...w};if(kind==='route'&&variant)w={index:variant==='lungs'?5:variant==='pa'?4:7,...w};if(kind==='airway'){renderDiagram('Air route and exchange surfaces','Trachea → bronchi → alveoli',lungFigure()+note,'AIRWAY OVERVIEW');return;}if(kind==='valve'){renderDiagram('One-way flow','A working valve prevents backflow',valveFigure('working','reverse',true)+note,'VALVE MODEL');return;}
 if(kind==='route'){const s=circuit[w.index||0];renderDiagram('Two linked circuits',s.name+' · '+s.oxygen,circuitFigure(w.index||0)+note,'TRACE THE CIRCULATION');return;}
 if(kind==='lungs'&&w.exchange){renderDiagram('Exchange across the alveolar wall','Equal model volumes · closed comparison',lungFigure(w)+note,'OXYGEN · CARBON DIOXIDE');return;}
 const part=bloodParts.find(p=>p.id===w.component)||bloodParts[0],name=kind==='heart'?'Inside the heart':kind==='vessels'?'Wall, lumen and valves':kind==='blood'?part.name:'An alveolus and its blood supply',diagram=(kind==='heart'?heartFigure(w):kind==='vessels'?vesselFigure(w):kind==='blood'?bloodFigure(part.id,true,w.on!==false):lungFigure(w))+note;
 renderCustomModel({name,formula:kind==='heart'?'Organ right is on your left':kind==='vessels'?'Compare structure with function':kind==='blood'?w.on===false?part.missing:part.result:'Air and blood are separated by thin walls',kicker:'SCHEMATIC CIRCULATION MODEL',atoms:[],bonds:[],radius:kind==='heart'?2.45:3,viewKey:'circ-'+kind,startPaused:true,note:'Symbolic anatomy · use labelled diagrams for orientation',aria:name+'. '+(kind==='blood'?(w.on===false?'Feature removed':'Feature present'):'Schematic, not to scale'),diagram,build:(g,T)=>buildCirculation(g,T,kind,w)});
}
export function mountCirculation(l,p,root,{save,done,feedback}){
 const w=p.widget,$=s=>root.querySelector(s),mode=l.widget,total=mode==='heart-lab'||mode==='blood-lab'?4:3;w.task??=0;w.passed??=[];const task=w.task%total;
 const field=(id,label,pairs,v)=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}">${opts(pairs,v)}</select>`;
 const tail='<button class="secondary" id="checkCirculation">Check reasoning</button><button class="secondary" id="nextCirculation">Next challenge →</button><p id="circulationProgress">'+w.passed.length+' / '+total+' complete</p>';
 const bind=(id,fn)=>{$('#'+id).onchange=e=>{w[id]=e.target.value;save();fn?.();};};let draw,valid,help;
 if(mode==='heart-lab'){
  if(task===0){const chambers=[['ra','Right atrium'],['rv','Right ventricle'],['la','Left atrium'],['lv','Left ventricle']];root.innerHTML='<p><b>1 / 4 · Match chamber roles</b></p>'+field('chamberView','Inspect a chamber',chambers,w.chamberView||'ra')+field('bodyReturn','Receives blood from the body',chambers,w.bodyReturn)+field('lungPump','Pumps blood to the lungs',chambers,w.lungPump)+field('lungReturn','Receives blood from the lungs',chambers,w.lungReturn)+field('bodyPump','Pumps blood to the body',chambers,w.bodyPump)+tail;draw=()=>showCirculation('heart',{selected:w.chamberView||'ra'});bind('chamberView',draw);for(let k of ['bodyReturn','lungPump','lungReturn','bodyPump'])bind(k);valid=()=>w.bodyReturn==='ra'&&w.lungPump==='rv'&&w.lungReturn==='la'&&w.bodyPump==='lv';help='Atria receive blood; ventricles pump it out. Right atrium→right ventricle→lungs; left atrium→left ventricle→body.';
  }else if(task===1){w.wallSeen??=[];root.innerHTML='<p><b>2 / 4 · Compare the ventricular walls</b></p>'+field('leftWall','Left ventricle wall',[['thick','Thicker muscle'],['thin','Thin muscle counterfactual']],w.leftWall||'thick')+'<button class="secondary" id="testHeartWall">Compare pumping role →</button><p id="heartWallReadout"></p>'+field('wallReason','Why is the left wall thicker?',[['body','Higher pressure for body circuit'],['blood','It makes the blood oxygenated'],['cells','It contains every blood cell']],w.wallReason)+tail;draw=()=>{showCirculation('heart',{thick:w.leftWall!=='thin',selected:'lv'});$('#heartWallReadout').textContent=w.leftWall==='thin'?'Less muscle would reduce the ability to generate the required pressure.':'Thicker muscle supports higher pressure for the body circuit; lungs use the right pump.';};bind('leftWall',draw);bind('wallReason');$('#testHeartWall').onclick=()=>{let k=w.leftWall||'thick';if(!w.wallSeen.includes(k))w.wallSeen.push(k);save();draw();};valid=()=>['thick','thin'].every(k=>w.wallSeen.includes(k))&&w.wallReason==='body';help='Compare both wall states. The left ventricle must generate higher pressure for systemic circulation; oxygen is added in the lungs, not by the muscle wall.';
  }else if(task===2){w.valveSeen??=[];root.innerHTML='<p><b>3 / 4 · Test one-way flow</b></p>'+field('valveState','Valve',[['working','Working'],['leaky','Leaky counterfactual']],w.valveState||'working')+field('flowDirection','Pressure pushes blood…',[['forward','Forwards'],['reverse','Backwards']],w.flowDirection||'forward')+'<button class="secondary" id="testValve">Test flow →</button><p id="valveReadout" aria-live="polite"></p>'+field('valveReason','Valve function',[['oneway','Prevents backward flow'],['oxygen','Adds oxygen to blood'],['beat','Creates the pacemaker signal']],w.valveReason)+tail;draw=()=>{renderDiagram('One-way valve comparison','Pressure and valve function',valveFigure(w.valveState||'working',w.flowDirection||'forward',!!w.lastValve)+note,'TEST FORWARD AND REVERSE FLOW');$('#valveReadout').textContent=w.lastValve||'Compare forward flow and attempted backflow.';};for(let k of ['valveState','flowDirection','valveReason'])bind(k);$('#testValve').onclick=()=>{const v=w.valveState||'working',d=w.flowDirection||'forward',key=v+':'+d;if(!w.valveSeen.includes(key))w.valveSeen.push(key);w.lastValve=valveFlow(v,d);save();draw();};valid=()=>['working:forward','working:reverse','leaky:reverse'].every(k=>w.valveSeen.includes(k))&&w.valveReason==='oneway';help='Test normal forward flow, working-valve backflow and leaky-valve backflow. Valves maintain direction; they do not oxygenate blood.';
  }else{w.paceSeen??=[];root.innerHTML='<p><b>4 / 4 · Separate control from blood supply</b></p>'+field('pacing','Signal model',[['natural','Natural resting pacemaker'],['irregular','Irregular signalling'],['artificial','Artificial pacemaker support']],w.pacing||'natural')+'<button class="secondary" id="testPacing">Observe signal pattern →</button><p id="paceReadout"></p>'+field('pacemakerSite','Natural resting pacemaker is in…',[['ra','Right atrium'],['lv','Left ventricle'],['aorta','Aorta']],w.pacemakerSite)+field('coronaryRole','Coronary arteries supply…',[['muscle','Supply heart muscle with oxygen'],['air','Air directly to the chambers'],['signals','Electrical signals only']],w.coronaryRole)+tail;draw=()=>{showCirculation('heart',{selected:'ra'});$('#paceReadout').textContent=w.pacing==='irregular'?'Uneven illustrative intervals:\n|  |    | |':w.pacing==='artificial'?'Device-supported regular signals:\n|  |  |  |':'Natural resting signals:\n|  |  |  |';};bind('pacing',draw);for(let k of ['pacemakerSite','coronaryRole'])bind(k);$('#testPacing').onclick=()=>{const v=w.pacing||'natural';if(!w.paceSeen.includes(v))w.paceSeen.push(v);save();draw();};valid=()=>['natural','irregular','artificial'].every(k=>w.paceSeen.includes(k))&&w.pacemakerSite==='ra'&&w.coronaryRole==='muscle';help='Compare all three signal patterns. The natural resting pacemaker is a group of cells in the right atrium; coronary arteries supply the muscle. The model is not an ECG or treatment recommendation.';}
 }else if(mode==='circulation-route'){
  if(task===0){w.routeIndex??=0;root.innerHTML='<p><b>1 / 3 · Follow one complete double circuit</b></p>'+field('nextStop','Next location',circuit.slice(1).map(s=>[s.id,s.name]),'')+'<button class="secondary" id="stepCircuit">Move blood →</button><p id="circuitReadout"></p>'+tail;draw=()=>{showCirculation('route',{index:w.routeIndex});$('#circuitReadout').textContent=(w.routeIndex+1)+' /11: '+circuit[w.routeIndex].name+' · '+circuit[w.routeIndex].oxygen;};$('#stepCircuit').onclick=()=>{if(w.routeIndex===10){feedback('Full circuit traced. Check your reasoning.');return;}if($('#nextStop').value!==circuit[w.routeIndex+1].id){feedback('Trace body→vena cava→right atrium→right ventricle→pulmonary artery→lungs→pulmonary vein→left atrium→left ventricle→aorta→body.',true);return;}w.routeIndex++;$('#nextStop').value='';save();draw();};valid=()=>w.routeIndex===10;help='Complete both circuits. A complete route visits the heart twice: once before lungs and once before the body.';
  }else if(task===1){const vessels=[['aorta','Aorta'],['vena','Vena cava'],['pa','Pulmonary artery'],['pv','Pulmonary vein']];root.innerHTML='<p><b>2 / 3 · Classify named vessels</b></p>'+vessels.map(([id,name])=>field('oxygen_'+id,name,[['higher','Higher oxygen'],['lower','Lower oxygen']],w['oxygen_'+id])).join('')+field('arteryDefinition','Arteries carry blood…',[['away','Away from the heart'],['oxygen','Always high in oxygen'],['toward','Towards the heart']],w.arteryDefinition)+tail;for(let [id]of vessels)bind('oxygen_'+id);bind('arteryDefinition');draw=()=>showCirculation('route',{index:4});valid=()=>w.oxygen_aorta==='higher'&&w.oxygen_pv==='higher'&&w.oxygen_vena==='lower'&&w.oxygen_pa==='lower'&&w.arteryDefinition==='away';help='Artery/vein describes direction relative to the heart. The pulmonary artery carries lower-oxygen blood to lungs; the pulmonary vein returns higher-oxygen blood.';
  }else{root.innerHTML='<p><b>3 / 3 · Calculate flow</b></p><p>Original model data:120cm³ passes a point in4s. Another circuit carries300cm³ in10s. Calculate mean volume per second; these are not patient measurements.</p><label class="field-label" for="flowOne">First flow / cm³s⁻¹</label><input class="lab-select" type="number" id="flowOne" value="'+(w.flowOne??'')+'"><label class="field-label" for="flowTwo">Second flow / cm³s⁻¹</label><input class="lab-select" type="number" id="flowTwo" value="'+(w.flowTwo??'')+'">'+field('flowCompare','Compare the mean flows',[['same','Equal mean flow rates'],['volume','Larger volume always means faster'],['none','Time is irrelevant']],w.flowCompare)+tail;for(let k of ['flowOne','flowTwo'])$('#'+k).oninput=e=>{w[k]=e.target.value;save();};bind('flowCompare');draw=()=>showCirculation('route',{index:10});valid=()=>Number(w.flowOne)===30&&Number(w.flowTwo)===30&&w.flowCompare==='same';help='Flow=volume÷time.120÷4=30 and300÷10=30cm³/s. Compare rates rather than volumes alone.';}
 }else if(mode==='vessel-lab'){
  const v=vesselCases[task];w.vessels??={};w.vessels[v.id]??={};const s=w.vessels[v.id];root.innerHTML=`<p><b>${task+1} / 3 · Build ${v.id==='artery'?'an':'a'} ${v.name.toLowerCase()}</b></p>`+field('vesselWall','Wall',[['thick','Thick muscle/elastic wall'],['thin','Thinner muscle/elastic wall'],['one','One-cell-thick exchange wall']],s.wall)+field('vesselLumen','Lumen',[['small','Relatively narrow'],['large','Relatively wide']],s.lumen)+field('vesselValve','Valves along this vessel model',[['yes','Present'],['no','Absent']],s.valve)+'<button class="secondary" id="testVessel">Inspect cross-section →</button>'+field('vesselReason','Structure supports…',[['pressure','High pressure away from heart'],['return','Low pressure; backflow control'],['exchange','Short exchange distance to tissues']],s.reason)+tail;draw=()=>showCirculation('vessels',s);for(let [id,key]of [['vesselWall','wall'],['vesselLumen','lumen'],['vesselValve','valve'],['vesselReason','reason']])$('#'+id).onchange=e=>{s[key]=e.target.value;if(key!=='reason')s.inspected=false;save();draw();};$('#testVessel').onclick=()=>{s.inspected=true;save();draw();};valid=()=>s.inspected&&vesselValid(v.id,s);help='Arteries have thick muscular/elastic walls; veins have wider lumens and valves for lower-pressure return; capillary walls are one cell thick for exchange. Views are separately enlarged, not a shared-size scale.';
 }else if(mode==='blood-lab'){
  const b=bloodParts[task];w.bloodSeen??={};w.bloodSeen[b.id]??=[];root.innerHTML=`<p><b>${task+1} / 4 · Investigate ${b.name.toLowerCase()}</b></p><p>Compare a normal role with a counterfactual missing function. This does not model every cause of disease.</p>`+field('bloodFeature',b.feature,[['on','Present/functional'],['off','Removed/impaired']],w.bloodFeature||'on')+'<button class="secondary" id="testBlood">Compare outcome →</button><p id="bloodReadout"></p>'+field('bloodReason','Main role',[['oxygen','Carry oxygen using haemoglobin'],['defence','Defend against pathogens'],['clot','Help clot at damaged vessels'],['transport','Carry dissolved substances']],w['bloodReason'+task])+tail;draw=()=>{showCirculation('blood',{component:b.id,on:w.bloodFeature!=='off'});$('#bloodReadout').textContent=w.bloodFeature==='off'?b.missing:b.result;};bind('bloodFeature',draw);$('#bloodReason').onchange=e=>{w['bloodReason'+task]=e.target.value;save();};$('#testBlood').onclick=()=>{const v=w.bloodFeature||'on';if(!w.bloodSeen[b.id].includes(v))w.bloodSeen[b.id].push(v);save();draw();};valid=()=>['on','off'].every(k=>w.bloodSeen[b.id].includes(k))&&w['bloodReason'+task]===b.reason;help='Compare both states and match the component to its role: red cells oxygen; white cells defence; platelets clotting; plasma transport of dissolved substances. Plasma also carries the suspended cells/fragments.';
 }else{
  if(task===0){w.lungViews??=[];root.innerHTML='<p><b>1 / 3 · Connect airway and blood supply</b></p><div class="model-actions"><button class="secondary" data-lungview="airway">Airway diagram</button><button class="secondary" data-lungview="alveolus">3D alveolus</button></div>'+field('airwayOrder','Air passes through…',[['route','Trachea → bronchi → alveoli'],['blood','Aorta → veins → trachea'],['cap','Capillaries → heart chambers']],w.airwayOrder)+field('lungNetwork','Alveoli are surrounded by…',[['capillaries','Capillary networks'],['bone','Solid bone'],['food','Digestive glands']],w.lungNetwork)+tail;for(let b of root.querySelectorAll('[data-lungview]'))b.onclick=()=>{let k=b.dataset.lungview;if(!w.lungViews.includes(k))w.lungViews.push(k);w.lungView=k;save();draw();};for(let k of ['airwayOrder','lungNetwork'])bind(k);draw=()=>w.lungView==='airway'?renderDiagram('Air route and gas-exchange surface','Air stays separate from the blood',lungFigure()+note,'TRACHEA · BRONCHI · ALVEOLI'):showCirculation('lungs');valid=()=>['airway','alveolus'].every(k=>w.lungViews.includes(k))&&w.airwayOrder==='route'&&w.lungNetwork==='capillaries';help='Inspect both views. Air travels via trachea and bronchi to alveoli. Capillaries surround alveoli; air does not flow directly into blood vessels.';
  }else if(task===1){w.gasStep??=0;root.innerHTML='<p><b>2 / 3 · Follow gas diffusion</b></p><p>Equal model volumes start with unequal gas amounts. Steps illustrate net movement, not breathing time or real gas composition.</p><button class="secondary" id="stepGas">Step exchange →</button><p id="gasReadout"></p>'+field('oxygenDirection','Oxygen net movement',[['blood','Alveolar air → blood'],['air','Blood → alveolar air'],['active','Only by active transport']],w.oxygenDirection)+field('carbonDirection','Carbon dioxide net movement',[['air','Blood → alveolar air'],['blood','Alveolar air → blood'],['stopped','No movement is possible']],w.carbonDirection)+field('gasReason','Driving cause',[['gradient','Diffusion down concentration gradients'],['heart','Heart makes oxygen atoms'],['food','Digestion across the lung wall']],w.gasReason)+tail;draw=()=>{showCirculation('lungs',{exchange:true,step:w.gasStep});let s=gasSnapshot(w.gasStep);$('#gasReadout').textContent=`O₂: air${s.oxygen.air}, blood${s.oxygen.blood}. CO₂: air${s.carbon.air}, blood${s.carbon.blood}. At equality there is no net movement, though molecules keep moving both ways.`;};$('#stepGas').onclick=()=>{w.gasStep=Math.min(2,w.gasStep+1);save();draw();};for(let k of ['oxygenDirection','carbonDirection','gasReason'])bind(k);valid=()=>w.gasStep===2&&w.oxygenDirection==='blood'&&w.carbonDirection==='air'&&w.gasReason==='gradient';help='Trace both net transfers. Oxygen diffuses from alveolar air into blood; carbon dioxide goes the opposite way. Equal concentration stops net movement, not all molecular motion.';
  }else{w.exchangeSeen??=[];for(let [k,v]of Object.entries({area:'normal',wall:'thin',air:'on',blood:'on'}))w[k]??=v;root.innerHTML='<p><b>3 / 3 · Test adaptations one at a time</b></p><p>Record the baseline, then change one factor at a time: area, wall thickness, ventilation and blood flow.</p>'+field('exchangeArea','Surface area',[['normal','Large area'],['reduced','Reduced area']],w.area)+field('exchangeWall','Wall',[['thin','Thin'],['thick','Thick']],w.wall)+field('exchangeAir','Ventilation',[['on','Air refreshed'],['off','No air refresh']],w.air)+field('exchangeBlood','Blood flow',[['on','Maintained'],['off','Stopped']],w.blood)+'<button class="secondary" id="testExchange">Compare adaptation →</button><p id="exchangeReadout"></p><ul id="exchangeHistory"></ul>'+field('exchangeReason','Effective exchange depends on…',[['all','Area, thin wall, gradients'],['colour','Blood colour only'],['thick','Thick walls and no circulation']],w.exchangeReason)+tail;draw=()=>{showCirculation('lungs',w);const r=exchangeCase(w);$('#exchangeReadout').textContent=r.effects.join('; ')||'Baseline: large area, short path, refreshed air and maintained blood flow.';$('#exchangeHistory').innerHTML=w.exchangeSeen.map(k=>'<li>'+({'normal:thin:on:on':'Baseline','reduced:thin:on:on':'Reduced area only','normal:thick:on:on':'Thicker wall only','normal:thin:off:on':'Ventilation stopped only','normal:thin:on:off':'Blood flow stopped only'}[k]||'Multiple factors changed')+'</li>').join('');};for(let [id,key]of [['exchangeArea','area'],['exchangeWall','wall'],['exchangeAir','air'],['exchangeBlood','blood']])$('#'+id).onchange=e=>{w[key]=e.target.value;save();draw();};bind('exchangeReason');$('#testExchange').onclick=()=>{const r=exchangeCase(w);if(!w.exchangeSeen.includes(r.key))w.exchangeSeen.push(r.key);save();draw();};valid=()=>exchangeComparisons.every(k=>w.exchangeSeen.includes(k))&&w.exchangeReason==='all';help='Record baseline, reduced area alone, thicker wall alone, stopped ventilation alone and stopped blood flow alone. Separate one cause at a time; air and blood refresh maintain the diffusion gradients.';}
 }
 $('#checkCirculation').onclick=()=>{if(!valid()){feedback(help,true);return;}if(!w.passed.includes(task))w.passed.push(task);if(w.passed.length===total){p.widgetDone=true;done();}save();$('#circulationProgress').textContent=w.passed.length+' / '+total+' complete';feedback('Evidence and explanation agree.');};$('#nextCirculation').onclick=()=>{if(!w.passed.includes(task)){feedback('Complete this challenge first.',true);return;}w.task=(task+1)%total;save();feedback('');mountCirculation(l,p,root,{save,done,feedback});};draw();
}
